const wheel=`<svg viewBox="0 0 100 100" aria-label="Kubernetes" role="img"><path fill="#3679e8" d="M50 2 88 20 98 61 72 94H28L2 61 12 20Z"/><g class="wheel" fill="none" stroke="white" stroke-width="5" stroke-linecap="round"><circle cx="50" cy="50" r="23"/>${Array.from({length:7},(_,i)=>`<path d="M50 15V43" transform="rotate(${i*360/7} 50 50)"/>`).join('')}<circle cx="50" cy="50" r="7" fill="white" stroke="none"/></g></svg>`;
const azure=`<svg viewBox="0 0 100 100" role="img" aria-label="Microsoft Azure"><path d="M40 8H65L32 91H7Z" fill="#147acf"/><path d="M65 8 95 91H32L43 64H62L49 31Z" fill="#169be2"/><path d="m43 64 52 27H32Z" fill="#0867b5"/></svg>`;
const courses={kubernetes:{title:'Kubernetes',label:'ORQUESTACIÓN DE CONTENEDORES',icon:wheel,description:'Comprende los clústeres, domina los contenedores y aprende a orquestar tus aplicaciones.',lessons:[['El mapa de un clúster','Kubernetes coordina aplicaciones en contenedores. Un clúster reúne un plano de control y nodos de trabajo. El plano de control gestiona el estado deseado; los nodos ejecutan las cargas de trabajo.','El API server recibe las peticiones. El scheduler asigna Pods a nodos. Los controladores reconcilian el estado actual con el deseado. En cada nodo, el kubelet supervisa los Pods.'],['Pods y Deployments','Un Pod es la unidad desplegable más pequeña de Kubernetes y puede contener uno o varios contenedores que comparten red y almacenamiento declarado.','Un Deployment gestiona réplicas de Pods mediante ReplicaSets. Describe cuántas réplicas necesitas y qué imagen deben ejecutar; sus controladores trabajan para mantener ese estado.'],['Services y comunicación','Los Pods pueden reemplazarse y cambiar de dirección IP. Un Service proporciona un punto de acceso estable a un conjunto de Pods seleccionado mediante etiquetas.','ClusterIP permite acceso interno. NodePort expone un puerto en los nodos. LoadBalancer solicita un balanceador externo cuando la infraestructura lo admite.'],['Configuración y namespaces','Un namespace delimita nombres y permite organizar recursos dentro de un clúster. ConfigMaps almacenan configuración no confidencial y Secrets están destinados a datos sensibles.','Base64 no es cifrado. La protección de Secrets depende también del control de acceso y de la configuración de cifrado en reposo. Un namespace por sí solo no garantiza aislamiento de red.']],labs:[{title:'Escala una aplicación',description:'Un Deployment llamado web tiene una réplica. Quieres mantener tres réplicas. ¿Qué comando usarías?',options:['kubectl scale deployment web --replicas=3','kubectl get pods --replicas=3','kubectl delete deployment web'],answer:0,explanation:'scale cambia el número deseado de réplicas del Deployment.',command:'kubectl scale deployment web --replicas=3\nkubectl get deployment web'},{title:'Conecta los Pods',description:'Una aplicación necesita acceder a otra dentro del clúster mediante una dirección estable. ¿Qué recurso es el más adecuado?',options:['Un Pod independiente','Un Service de tipo ClusterIP','Un namespace nuevo'],answer:1,explanation:'Un Service ClusterIP ofrece un punto de acceso estable dentro del clúster.'}]},azure:{title:'Microsoft Azure',label:'COMPUTACIÓN EN LA NUBE',icon:azure,description:'Explora la nube, conoce sus servicios y construye una base sólida para tus proyectos en Azure.',lessons:[['Fundamentos de la nube','La computación en la nube permite consumir capacidad de cómputo, almacenamiento y redes como servicios. Puedes ajustar los recursos a las necesidades de tu aplicación.','En IaaS administras, entre otras cosas, el sistema operativo. En PaaS el proveedor gestiona más infraestructura. En SaaS consumes una aplicación. La responsabilidad de seguridad se comparte y varía según el servicio.'],['Organiza tus recursos','Una suscripción agrupa recursos con un contexto de facturación y control de acceso. Un grupo de recursos es un contenedor lógico para recursos relacionados.','Una región es un área geográfica donde Azure ofrece infraestructura. Las zonas de disponibilidad, cuando están disponibles para el servicio y región, ayudan a distribuir recursos entre ubicaciones físicas separadas.'],['Cómputo, red y almacenamiento','Las máquinas virtuales ofrecen control sobre el sistema operativo. App Service permite alojar aplicaciones web. Azure Kubernetes Service (AKS) ofrece Kubernetes administrado.','Una red virtual conecta recursos de forma privada. Blob Storage almacena objetos, como imágenes o copias de seguridad. Elige el servicio a partir de las necesidades de la aplicación.'],['Identidad y acceso','Microsoft Entra ID proporciona servicios de identidad. Azure RBAC permite asignar permisos a identidades sobre recursos con un ámbito definido.','Aplica el principio de mínimo privilegio: concede únicamente los permisos necesarios. Las identidades administradas ayudan a que una aplicación acceda a servicios compatibles sin guardar credenciales en su código.']],labs:[{title:'Elige el servicio adecuado',description:'Tu aplicación ya utiliza Kubernetes y quieres ejecutar su clúster en un servicio administrado de Azure. ¿Qué elegirías?',options:['Azure Blob Storage','Azure Kubernetes Service (AKS)','Microsoft Entra ID'],answer:1,explanation:'AKS es el servicio de Kubernetes administrado de Azure.'},{title:'Aplica mínimo privilegio',description:'Una persona solo necesita consultar los recursos de un grupo. ¿Qué rol integrado se ajusta mejor?',options:['Owner','Contributor','Reader'],answer:2,explanation:'Reader permite consultar recursos sin modificarlos. Asigna el rol en el ámbito del grupo requerido.'}]}};
let done={};try{done=JSON.parse(localStorage.getItem('cloudlab-progress')||'{}')||{};}catch{}function save(){try{localStorage.setItem('cloudlab-progress',JSON.stringify(done));}catch{}}const app=document.querySelector('#app');
function progress(key){const c=courses[key];const count=[...c.lessons.map((_,i)=>`${key}-t-${i}`),...c.labs.map((_,i)=>`${key}-p-${i}`)].filter(id=>done[id]).length;return{count,total:c.lessons.length+c.labs.length,percent:Math.round(count/(c.lessons.length+c.labs.length)*100)}}
function card(key){let c=courses[key],p=progress(key);return `<article class="course"><div class="course-top"><div class="course-id"><div class="logo-box">${c.icon}</div><span class="tag">${c.label}</span></div><h2>${c.title}</h2><p>${c.description}</p><div class="progress-label"><span>Tu progreso</span><b>${p.percent}% completado</b></div><div class="progress"><i style="width:${p.percent}%"></i></div></div><div class="course-links"><a href="#${key}/teoria"><span class="link-icon">▥</span><div><strong>Teoría</strong><small>Entiende los conceptos esenciales · 4 lecciones</small></div><span class="arrow">↗</span></a><a href="#${key}/practica"><span class="link-icon">⌘</span><div><strong>Práctica</strong><small>Pon a prueba lo que sabes · 2 ejercicios</small></div><span class="arrow">↗</span></a>${key==='kubernetes'?`<a href="#kubernetes/docs"><span class="link-icon">☰</span><div><strong>Documentación</strong><small>Apuntes con diagramas · 10 capítulos</small></div><span class="arrow">↗</span></a>`:''}${key==='azure'?`<a href="#examen"><span class="link-icon">▤</span><div><strong>Simulador AZ-900</strong><small>Prepárate para la certificación · ${window.az900Stats().total} preguntas</small></div><span class="arrow">↗</span></a>`:''}</div></article>`}
function tabs(key,part){return`<div class="tabs"><a href="#${key}/teoria" class="${part!=='practica'&&part!=='docs'?'selected':''}">▥ &nbsp; Teoría</a><a href="#${key}/practica" class="${part==='practica'?'selected':''}">⌘ &nbsp; Práctica</a>${key==='kubernetes'?`<a href="#${key}/docs" class="${part==='docs'?'selected':''}">☰ &nbsp; Documentación</a>`:''}</div>`}
function home(){app.innerHTML=`<p class="eyebrow">TU PRÓXIMO PASO EMPIEZA AQUÍ</p><h1>Aprende hoy. Construye mañana.</h1><p class="intro">Tu espacio para dominar Kubernetes y Azure, un concepto a la vez.</p><section class="hero"><div class="hero-copy"><span class="pill"><span class="status-dot"></span> DE LA TEORÍA A LA PRÁCTICA</span><h2>Dos tecnologías.<br>Un mundo de posibilidades.</h2><p>Explora los fundamentos, experimenta con ejercicios y prepara tu próximo desafío en la nube.</p></div><div class="hero-art"><div class="art-tile">${wheel}</div><span class="plus">+</span><div class="art-tile">${azure}</div></div></section><div class="section-head"><div><h2>Elige tu ruta de aprendizaje</h2><p>Cada gran proyecto comienza por entender las bases.</p></div><span>2 rutas disponibles</span></div><div class="cards">${card('kubernetes')}${card('azure')}</div><a href="#examen" class="exam-banner"><span class="exam-icon">▤</span><div><h3>Simulador de examen AZ-900</h3><p>${window.az900Stats().total} preguntas tipo examen con explicación en español. Llevas ${window.az900Stats().answered} respondidas.</p></div><span class="pill"><span class="status-dot"></span> Disponible</span></a><p class="bottom-note">✧ &nbsp; Sin prisa, pero sin pausa. Tu progreso se guarda en este navegador.</p>`}
function render(){const [route,part]=location.hash.slice(1).split('/');const key=courses[route]?route:null;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(key|| (route==='examen'?'examen':'inicio'))));document.querySelector('#crumb').textContent=key?courses[key].title:route==='examen'?'Simulador AZ-900':'Vista general';if(!key){if(route==='examen')window.renderExam(app,part);
else home();return}if(key==='kubernetes'&&part==='docs'){window.renderK8sDocs(app,tabs(key,part));return}const c=courses[key],practice=part==='practica';app.innerHTML=`<a class="back" href="#inicio">← Todas las rutas</a><p class="eyebrow">${c.label}</p><h1>${c.title}</h1><p class="intro">${c.description}</p>${tabs(key,part)}${practice&&key==='kubernetes'?'<section class="k8s-lab" id="k8s-lab"></section>':''}${practice&&key==='azure'?'<section class="k8s-lab" id="az-lab"></section>':''}<div class="section-head"><div><h2>${practice?'Comprueba lo que sabes':'Primero, las bases'}</h2><p>${practice?'Ejercicios guiados de conocimiento. No ejecutan recursos en la nube.':'Abre una lección y márcala como completada cuando la termines.'}</p></div></div>${practice?c.labs.map((l,i)=>`<form class="lesson" data-lab="${i}"><h3>0${i+1} &nbsp; ${l.title} ${done[`${key}-p-${i}`]?'✓':''}</h3><p>${l.description}</p>${l.options.map((o,j)=>`<label class="option"><input type="radio" name="answer" value="${j}" required>${o}</label>`).join('')}<button class="btn primary" type="submit">Comprobar respuesta</button><div class="feedback" role="status"></div></form>`).join(''):c.lessons.map((l,i)=>`<details class="lesson" ${i===0?'open':''}><summary>0${i+1} &nbsp; ${l[0]}</summary><p>${l[1]}</p><p>${l[2]}</p><button class="btn ${done[`${key}-t-${i}`]?'':'primary'}" data-complete="${key}-t-${i}">${done[`${key}-t-${i}`]?'✓ Lección completada':'Marcar como completada'}</button></details>`).join('')}<p class="bottom-note">Tu progreso se guarda en este navegador.</p>`;const lab=app.querySelector('#k8s-lab');if(lab)window.mountK8sLab(lab);const azLab=app.querySelector('#az-lab');if(azLab)window.mountAzLab(azLab);
app.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{done[b.dataset.complete]=!done[b.dataset.complete];save();b.textContent=done[b.dataset.complete]?'✓ Lección completada':'Marcar como completada';b.classList.toggle('primary',!done[b.dataset.complete])});app.querySelectorAll('[data-lab]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const i=+f.dataset.lab,l=c.labs[i],ok=+new FormData(f).get('answer')===l.answer;f.querySelector('.feedback').innerHTML=ok?`✓ ¡Correcto! ${l.explanation}${l.command?`<pre><code>${l.command}</code></pre>`:''}`:'Todavía no. Revisa el concepto e inténtalo de nuevo.';if(ok){done[`${key}-p-${i}`]=true;save();f.querySelector('h3').textContent=`0${i+1}  ${l.title} ✓`}})}window.addEventListener('hashchange',()=>{render();if(!location.hash.split('/')[2])window.scrollTo(0,0)});render();
